const fruits = [
    "Apple",
    "Banana",
    "Orange"
];

const result = fruits.includes("Orange");

console.log(result);

const user = {
    name: "Alex"
};

const users = [
    user
];

console.log(users.includes(user));

const users = [
    {
        name: "Alex"
    }
];

console.log(
    users.includes({
        name: "Alex"
    })
);
